149:@router.post("/mcp/call/{tool}")
150:async def pivete_mcp_call(tool: str, request: Request) -> dict[str, Any]:
151:    _pivete_auth(request)
152:    try:
153:        payload = await request.json()
154:    except Exception:
155:        payload = {}
156:
157:    log_dir = REPO_ROOT / "logs"
158:    log_dir.mkdir(parents=True, exist_ok=True)
159:    log_file = log_dir / f"pivete-mcp-{time.strftime('%Y-%m-%d')}.jsonl"
160:    entry = {
161:        "ts": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
162:        "tool": tool,
163:        "input_keys": list(payload.keys()) if isinstance(payload, dict) else [],
164:        "origem": "webui/pivete-compat",
165:    }
166:    try:
167:        with log_file.open("a", encoding="utf-8") as handle:
168:            handle.write(json.dumps(entry) + "\n")
169:    except Exception:
170:        pass
171:
172:    try:
173:        cmd = [
174:            "node",
175:            str(REPO_ROOT / "apps/modulos/mcp/dist/cli/call.js"),
176:            tool,
177:            json.dumps(payload),
178:        ]
179:        proc = subprocess.run(cmd, capture_output=True, timeout=60, text=True)
180:        if proc.returncode != 0:
181:            return {"ok": False, "erro": proc.stderr[:2000], "tool": tool}
182:        try:
183:            return {"ok": True, "tool": tool, "resultado": json.loads(proc.stdout)}
184:        except Exception:
185:            return {"ok": True, "tool": tool, "resultado": proc.stdout[:5000]}
186:    except FileNotFoundError:
187:        return {"ok": False, "erro": "cli/call.js ausente; MCP local nao comprovado"}
188:    except subprocess.TimeoutExpired:
189:        return {"ok": False, "erro": "timeout 60s"}
190:    except Exception as exc:  # noqa: BLE001
191:        return {"ok": False, "erro": type(exc).__name__}
